/* Turn one row into a friendly object, e.g. NRA_WC_GET(0).name */
window.NRA_WC_GET = function(i){
  const r = window.NRA_WORLD_CITIES[i];
  return { name:r[0], cc:r[1], country:window.NRA_COUNTRY_NAMES[r[1]]||r[1],
           admin:r[2], pop:r[3], lat:r[4], lng:r[5], capital:!!r[6],
           iata:r[7], ownAirport:!!r[8], aviationScore:r[9],
           indexScore:r[10], poiScore:r[11], visitorScore:r[12] };
};
